class RuleWithValue(Rule):
    value: Any

    def __eq__(self, other):
        return isinstance(other, self.__class__) and self.value == other.value

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(value={self.value})"

    @property
    def __dict__(self):
        return {
            **super().__dict__,
            "value": self.value,
        }


