): pointer is GraphPointer<RuleCharExclude> => isRuleCharExclude(pointer.rule);

export const isResolvedRule = (rule?: UnresolvedRule): rule is ResolvedRule =>
  isRuleChar(rule) || isRuleCharExclude(rule) || isRuleEnd(rule);

