        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
    )
    return f"'{body}'"


def js_ord(n: int) -> str:
    if 32 <= n <= 126:
        ch = chr(n)
        if ch == "'":
            return "ord(\"'\")"
        if ch == "\\":
            return "ord('\\\\')"
        return f"ord('{ch}')"
    return str(n)


def js_expected_value(v) -> str:
    if isinstance(v, list):
        return "[" + ", ".join(js_ord(x) for x in v) + "]"
    return js_ord(v)


def js_rule(rule: dict) -> str:
    if rule["type"] == "end":
        return "{ type: 'end' }"
    values = ", ".join(js_expected_value(v) for v in rule["value"])
    return f"{{ type: '{rule['type']}', value: [{values}] }}"


