    lines = ["["]
    lines += [f"        {js_rule(r)}," for r in rules]
    lines.append("      ]")
    return "\n".join(lines)


def js_arg(v) -> str:
    if isinstance(v, str):
        return js_str(v)
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)


